const meta = $input.first().json;

return Object.entries(meta).map(([username, data]) => ({
  json: {
    username,
    processedQuestions: typeof data.questions === 'object' && !Array.isArray(data.questions) ? Object.keys(data.questions) : data.questions || []
  }
}));

const inputItems = $input.all();           // graphql responses, one per user
const userItems = $('split-per-user1').all(); // user data, same order

const results = [];

for (let i = 0; i < inputItems.length; i++) {
  const username = userItems[i].json.username;
  const rawProcessedQuestions = userItems[i].json.processedQuestions || [];
  const processedQuestions = Array.isArray(rawProcessedQuestions) ? rawProcessedQuestions : Object.keys(rawProcessedQuestions);
  const allSubmissions = inputItems[i].json?.data?.recentAcSubmissionList || [];

  const seenSlugs = new Set();

  for (const sub of allSubmissions) {
    if (
      !seenSlugs.has(sub.titleSlug) &&
      !processedQuestions.includes(sub.titleSlug)
    ) {
      seenSlugs.add(sub.titleSlug);
      results.push({ json: { ...sub, username, solvedAt: new Date(sub.timestamp * 1000).toISOString().split('T')[0] } });
    }
  }
}

return results.length > 0 ? results : [{ json: { skip: true } }];

